  listen(host,'click',interceptManual,true);
  listen(doc, 'pointerdown', e => {
    if (!device || e.button !== 0 || e.isPrimary === false || !device.contains(e.target)) return;
    if (!e.target.closest('.wave-statusbar,.wave-appbar,.ks-roster-header') || e.target.closest('button,input,select,textarea,a,.device-status,.music-island-v2')) return;
    e.preventDefault();
    try { device.setPointerCapture?.(e.pointerId); } catch {}
    dragging = { id: e.pointerId, x: lastLayout.x, y: lastLayout.y, startX: e.clientX, startY: e.clientY };
  });
  listen(doc, 'pointermove', e => {
    if (!dragging || e.pointerId !== dragging.id) return;
    if (Math.abs(e.clientX - dragging.startX) + Math.abs(e.clientY - dragging.startY) < 5) return;
    e.preventDefault(); preferred.x = dragging.x + e.clientX - dragging.startX; preferred.y = dragging.y + e.clientY - dragging.startY; layout();
  }, { passive: false });
  const endDrag = e => { if (dragging && dragging.id === e.pointerId) { dragging = null; preferred.x = lastLayout.x; preferred.y = lastLayout.y; persistGeometry(); } };
  listen(doc, 'pointerup', endDrag); listen(doc, 'pointercancel', endDrag);
  listen(doc, 'click', e => { if (layerMode && e.target.closest?.('.wave-homebar') && device?.contains(e.target)) { e.preventDefault(); e.stopImmediatePropagation(); closeLayer(); } }, true);
